{
  "root": "main_stack",
  "state": {
    "journey_steps": [
      {
        "stepNumber": "1",
        "title": "From Times Square to Fifth Avenue",
        "description": "Start Point: Begin your walk at the intersection of W 47th Street and Broadway in Times Square.\nWalk North: Head north on 7th Avenue (which merges with Broadway), immersing yourself in the dazzling billboards and vibrant atmosphere of the Theater District.\nTurn East: At W 49th Street, turn right (east) and walk across 6th Avenue (Avenue of the Americas).\nReach Fifth Avenue: Continue east for two more blocks until you reach Fifth Avenue.",
        "notableSights": "Broadway Theaters, and visible glimpses of Rockefeller Center (to your left once on 5th Ave).",
        "estimatedTime": "25-30 minutes"
      },
      {
        "stepNumber": "2",
        "title": "Along Fifth Avenue to Central Park South",
        "description": "Continue North: Proceed north on Fifth Avenue. This stretch is renowned for its luxury boutiques and grand historic buildings.",
        "notableSights": "You'll pass St. Patrick's Cathedral (on 5th Ave between 50th and 51st Streets), high-end shops, Trump Tower (at 56th Street), and eventually arrive at The Plaza Hotel at the southeast corner of Central Park (59th Street).",
        "estimatedTime": "15-20 minutes"
      },
      {
        "stepNumber": "3",
        "title": "Through Central Park to Bethesda Terrace",
        "description": "Enter Central Park: Cross 59th Street at Grand Army Plaza and enter Central Park.\nFollow The Mall: Take the main path directly into the park, which will lead you onto The Mall, a wide, tree-lined promenade. This iconic pathway is often featured in films.\nReach Bethesda: Follow The Mall north, which culminates at the beautiful Bethesda Terrace and Fountain, a central architectural and artistic feature of Central Park.",
        "notableSights": "Grand Army Plaza, The Pond (to your left after entering), Central Park Zoo (to your right, behind trees), The Mall, Literary Walk, and finally, Bethesda Terrace and Fountain.",
        "estimatedTime": "20-25 minutes"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "header_stack",
        "intro_text",
        "journey_title",
        "journey_table",
        "quick_actions_title",
        "google_maps_button",
        "central_park_button",
        "sources_title",
        "google_maps_source_button",
        "central_park_conservancy_source_button"
      ]
    },
    "header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "geo_icon",
        "title_text"
      ]
    },
    "geo_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000241_01_10_geo-alt.svg"
      },
      "children": []
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "New York City Walking Tour: Times Square to Bethesda Terrace",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Embark on a vibrant walk from the bustling heart of Times Square to the serene beauty of Central Park's iconic Bethesda Terrace. This route guides you past famous Midtown landmarks and through a scenic portion of Central Park. The total distance is approximately 1.8 miles (2.9 km), and the estimated walking time is 60-75 minutes at a comfortable pace, allowing for brief stops to enjoy the sights."
      },
      "children": []
    },
    "journey_title": {
      "type": "Text",
      "props": {
        "text": "Your Journey: Times Square to Bethesda Terrace",
        "variant": "h2"
      },
      "children": []
    },
    "journey_table": {
      "type": "Table",
      "props": {
        "statePath": "/journey_steps",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "title",
        "highlightColumns": ["estimatedTime"],
        "columns": [
          {
            "key": "stepNumber",
            "label": "Step"
          },
          {
            "key": "title",
            "label": "Section"
          },
          {
            "key": "description",
            "label": "Details"
          },
          {
            "key": "notableSights",
            "label": "Sights"
          },
          {
            "key": "estimatedTime",
            "label": "Time"
          }
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "google_maps_button": {
      "type": "Button",
      "props": {
        "label": "View Route on Google Maps"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/maps/dir/Times+Square,+Manhattan,+NY/Bethesda+Terrace,+New+York,+NY/"
          }
        }
      },
      "children": []
    },
    "central_park_button": {
      "type": "Button",
      "props": {
        "label": "Explore Central Park"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.centralparknyc.org/"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "google_maps_source_button": {
      "type": "Button",
      "props": {
        "label": "Google Maps"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/maps/"
          }
        }
      },
      "children": []
    },
    "central_park_conservancy_source_button": {
      "type": "Button",
      "props": {
        "label": "Central Park Conservancy"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.centralparknyc.org/"
          }
        }
      },
      "children": []
    }
  }
}
